#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, l = 0, m = 0, n = 0, r = 0, t = 0;
    // 本平台完整输入是 n、target、数组；函数参数直接给出数组和 target。
    n = read();
    t = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    l = 0;
    r = n;
    // 维护左闭右开区间，r 可以等于 n；比较后保留可能的分界点。
    while (l < r)  {
        m = ((l + r) / 2);
        if (a[m] < t)  {
            l = (m + 1);
        }
        else  {
            r = m;
        }
    }
    // l 是第一个不小于目标的位置；等于 n 时表示插在末尾。
    emit(l);
    return 0;
}

